-- fixture: all-three-valued-false-after-unknown
-- form: all(value(unknown), kind(false))
WITH packed AS MATERIALIZED (SELECT * FROM rerail_matches WHERE batch = :batch), producer_status AS MATERIALIZED (SELECT * FROM packed WHERE row_kind = 2), terminal_match AS MATERIALIZED (SELECT * FROM packed WHERE row_kind = 3), fact AS MATERIALIZED (SELECT * FROM packed WHERE row_kind = 6), candidates AS (SELECT match.* FROM terminal_match match JOIN producer_status status USING (producer_id, file_index) WHERE match.producer_id = 0 AND status.complete = 1), truth AS (SELECT candidates.*, CASE WHEN rejected.node IS NULL THEN 0 WHEN value.verdict IS NULL THEN NULL ELSE value.verdict END AS relational_verdict FROM candidates LEFT JOIN fact value ON value.producer_id = 1 AND value.file_index = candidates.file_index AND value.node = candidates.node LEFT JOIN terminal_match rejected ON rejected.producer_id = 2 AND rejected.file_index = candidates.file_index AND rejected.node = candidates.node) SELECT * FROM truth WHERE relational_verdict = 1 ORDER BY file_index, node, producer_id, match_index;

